$dean = \App\Models\User::where("email", "like", "%dean%")->first(); echo "Dean: " . $dean->name . " - College ID: " . $dean->college_id . "\n"; $deanRole = \Spatie\Permission\Models\Role::where("name", "Dean")->first(); echo "Dean role exists: " . ($deanRole ? "Yes" : "No") . "\n"; if ($deanRole) { echo "Dean permissions: "; $deanRole->permissions()->pluck("name")->each(function($p) { echo $p . ", "; }); } echo "\n";